/**
 * One-time provisioning for the encrypted off-site database backup bucket.
 *
 * Creates the backup bucket (private) in the configured Spaces region using the
 * credentials already on the box, then proves those credentials can reach it and
 * that an anonymous listing is refused. Idempotent — safe to re-run.
 *
 * It deliberately does NOT touch the encryption key. A disaster-recovery key
 * generated by automation and stored only on the box it protects is not a
 * recovery plan; the operator sets JURVIO_BACKUP_ENCRYPTION_KEY and keeps a copy
 * elsewhere. This job reports whether that key is present, never its value.
 *
 * Usage:
 *   node jobs/provision-backup-bucket.mjs
 *   node jobs/provision-backup-bucket.mjs --bucket jurvio-db-backups
 */
import {
  OffsiteBackupStore,
  resolveBackupBucketTarget,
} from "@/modules/operations/application/offsite-backup";

function arg(name: string): string | null {
  const prefixed = process.argv.find((value) => value.startsWith(`--${name}=`));
  if (prefixed) return prefixed.slice(name.length + 3);
  const index = process.argv.indexOf(`--${name}`);
  return index >= 0 ? (process.argv[index + 1] ?? null) : null;
}

async function main() {
  const requested = arg("bucket");
  const target = resolveBackupBucketTarget(
    requested ? { ...process.env, JURVIO_BACKUP_BUCKET: requested } : process.env,
  );
  const store = new OffsiteBackupStore(target);
  const result = await store.ensureBucket();

  const keyConfigured = Boolean(process.env.JURVIO_BACKUP_ENCRYPTION_KEY);
  console.log(
    JSON.stringify({
      report: "provision-backup-bucket",
      bucket: result.bucket,
      endpoint: target.host,
      region: target.region,
      created: result.created,
      alreadyExisted: !result.created,
      publiclyListable: result.publiclyListable,
      encryptionKeyConfigured: keyConfigured,
    }),
  );

  if (result.publiclyListable) {
    console.error(
      `::error::bucket ${result.bucket} allows anonymous listing. Make it private ` +
        "before any backup is uploaded to it.",
    );
    process.exit(1);
  }
  if (!keyConfigured) {
    // Not a failure of provisioning — the bucket is ready — but the operator
    // still has a required step, so say so in a way a run summary shows.
    console.error(
      "::warning::JURVIO_BACKUP_ENCRYPTION_KEY is not set in /opt/jurvio/.env.production. " +
        "Generate one with `openssl rand -base64 32`, add it there (mode 600), and keep a " +
        "copy off this box. Uploads will fail until it is set.",
    );
  }
  console.log(
    `Backup bucket ${result.bucket} is ${result.created ? "created" : "present"} and private.`,
  );
}

main().catch((error) => {
  console.error(`::error::${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
});
